import io, json, os, time, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
MODEL = 'qwen2.5:14b'
TIMEOUT = 1500
LANE = 'cpu'
CPU_THREADS = 4      # CEO 10% CPU margin law (O-20260913-2215)
GENERATE_URL = 'http://localhost:11434/api/generate'
MATERIAL = 'MC-20261012-DIGEST-v19 static card (cards.json + render output + e4-material.md)'
prompt = '你是一名刷公众号图文/信息流的普通读者，看到下面这张静态盘点卡《城市盘点 019》（1080×1080 方图·黑底；左上角小字「[AIGC·AI 生成内容]」；顶部大标题「城市盘点 019」）。图上写着七行盘点正文：「顶层梳理日（10-12 · 两日 22 行令批）」；「导演拍板，不要都来问我，我看到问题自然会说，没说你们就自己推进。」——这行是老板原话引文；「顶层梳理案同窗收口 · 票档 7/7 · 判据 6 条」；「四阶段推进 · 盘点 瘦身 治理 常态」；「法熵守恒 · 新增 ≤3 节 · 退役并档 ≥3 处」；「三席定律成形 · 道具 调色 服装 三签字闸」。图内底部声明行「基于硅基城市真实事件（顶层梳理日令批台账档案）」。背景：硅基城市是一家由 AI 全自主运转的公司集团（只有一个人类老板，其余成员全是 AI）。「城市盘点」系列是集团旗下媒体公司出品的城市档案盘点图——把集团真实发生的大事，用数字盘点的方式做成一张方图档案，所以底部声明行写明「基于硅基城市真实事件」。这张卡盘点的是 10 月 12 日的「顶层梳理日」：老板说业务越来越多越来越复杂，点名决策委员会从顶层开始梳理规则、制度、流程和工作流——执行案当天就收口通过，票档 7/7，预注册 6 条验收判据，分四阶段推进（盘点、瘦身、治理、常态）；同一波令批里，集团的音乐 MV 产线立起「三席定律」：道具、调色、服装三道签字闸；导演拍板权同日生效——老板只留一句「导演拍板，不要都来问我，我看到问题自然会说，没说你们就自己推进」。\n请回答三个问题，每题一段，直说不委婉：\n1) 刷到这张卡你会停下来看吗？会保存或转发给朋友吗？打几分（0-10）？为什么？\n2) 有没有一眼假、空洞套话的地方？有的话扣几分、指出原句？\n3) 最弱的一项是什么？'

result = {'ts': time.strftime('%Y-%m-%d %H:%M:%S'), 'model': MODEL,
          'material': MATERIAL, 'lane': LANE}
payload = json.dumps({'model': MODEL, 'prompt': prompt, 'stream': False,
                      'options': {'num_gpu': 0,
                                  'num_thread': CPU_THREADS}}).encode('utf-8')
request = urllib.request.Request(GENERATE_URL, data=payload,
                                 headers={'Content-Type': 'application/json'})
try:
    with urllib.request.urlopen(request, timeout=TIMEOUT) as resp:
        body = json.loads(resp.read().decode('utf-8', 'replace'))
    result['verdict'] = (body.get('response') or '').strip() or \
        'EMPTY-RESPONSE'
except Exception as exc:
    text = '%s: %s' % (type(exc).__name__, exc)
    if 'timed out' in text.lower() or 'timeout' in text.lower():
        result['verdict'] = 'TIMEOUT-%ds' % TIMEOUT
    else:
        print('TRANSPORT-ERROR %s' % text, flush=True)
        raise SystemExit(3)
io.open(os.path.join(HERE, 'e4-result.json'), 'w', encoding='utf-8').write(
    json.dumps(result, ensure_ascii=False, indent=2))
print('DONE' if not result['verdict'].startswith('TIMEOUT') else 'TIMEOUT')
